-- Migration: 20261017000002_google_business_reviews.sql
-- Description: Create tables for automated Google Business Profile reviews and platform rating metrics

-- 1. BUSINESS REVIEWS TABLE
CREATE TABLE IF NOT EXISTS public.business_reviews (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  google_review_id TEXT UNIQUE,
  author_name TEXT NOT NULL,
  author_display_name TEXT,
  author_photo_url TEXT,
  rating INT NOT NULL CHECK (rating >= 1 AND rating <= 5),
  review_text TEXT,
  original_time TIMESTAMPTZ,
  relative_time_description TEXT,
  source TEXT DEFAULT 'google',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_business_reviews_rating ON public.business_reviews (rating);
CREATE INDEX IF NOT EXISTS idx_business_reviews_created_at ON public.business_reviews (created_at DESC);

-- 2. BUSINESS STATS TABLE
CREATE TABLE IF NOT EXISTS public.business_stats (
  key TEXT PRIMARY KEY,
  average_rating NUMERIC(3, 2) DEFAULT 4.85,
  total_reviews INT DEFAULT 1420,
  place_id TEXT,
  place_name TEXT DEFAULT 'Carpenterwala Bangalore',
  last_synced_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. ENABLE ROW LEVEL SECURITY & PUBLIC READ POLICIES
ALTER TABLE public.business_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.business_stats ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read business_reviews" ON public.business_reviews;
CREATE POLICY "Allow public read business_reviews" ON public.business_reviews FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow service role all business_reviews" ON public.business_reviews;
CREATE POLICY "Allow service role all business_reviews" ON public.business_reviews FOR ALL USING (true);

DROP POLICY IF EXISTS "Allow public read business_stats" ON public.business_stats;
CREATE POLICY "Allow public read business_stats" ON public.business_stats FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow service role all business_stats" ON public.business_stats;
CREATE POLICY "Allow service role all business_stats" ON public.business_stats FOR ALL USING (true);

-- 4. INSERT DEFAULT SUMMARY STATS IF NOT EXISTS
INSERT INTO public.business_stats (key, average_rating, total_reviews, place_name, last_synced_at)
VALUES ('google_reviews_summary', 4.85, 1420, 'Carpenterwala Bangalore', NOW())
ON CONFLICT (key) DO NOTHING;

